import{_ as a,o as n,c as t,a2 as s}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-21","description":"","frontmatter":{"title":"AI 动态 · 2026-11-21","date":"2026-11-21T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-21.md","filePath":"news/2026-11/ai-news-2026-11-21.md","lastUpdated":null}'),r={name:"news/2026-11/ai-news-2026-11-21.md"};function i(o,e,l,c,p,h){return n(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-11-21" tabindex="-1">AI 动态 · 2026-11-21 <a class="header-anchor" href="#ai-动态-·-2026-11-21" aria-label="Permalink to &quot;AI 动态 · 2026-11-21&quot;">​</a></h1><blockquote><p>截至 2026-11-21。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-briefing" data-section="今日导读"><h2 id="今日导读" tabindex="-1">今日导读 <a class="header-anchor" href="#今日导读" aria-label="Permalink to &quot;今日导读&quot;">​</a></h2><ol><li>今日最大看点是黎曼猜想的双重进展：Anthropic 数学家 Levent Alpöge 声称与 Claude 合作给出 Lean 形式化证明，同时数学家 Ravi Vakil 透露另一份纯人类证明正在推进，AI 与数学的边界被同时推向新高度。</li><li>产业侧，黄仁勋辞职后英伟达董事会拒绝其回归、林俊旸新公司估值翻倍至 50 亿美元、Anthropic 上市后治理结构受质疑，AI 资本与权力格局持续震荡。</li><li>模型与工具层，OpenAI 发布 GPT-Live-1.1 语音模型并下调闲置计费，Thinking Machines 推出可在 32GB Mac 运行的 26B MoE 模型，端侧与低成本推理成为新战场。</li></ol></div><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="头条-·-黎曼猜想被证明-34-岁数学家借-claude-放出-lean-形式化证明" tabindex="-1">头条 · 黎曼猜想被证明？34 岁数学家借 Claude 放出 Lean 形式化证明 <a class="header-anchor" href="#头条-·-黎曼猜想被证明-34-岁数学家借-claude-放出-lean-形式化证明" aria-label="Permalink to &quot;头条 · 黎曼猜想被证明？34 岁数学家借 Claude 放出 Lean 形式化证明&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-11-21">2026-11-21</time></p><p>Anthropic 数学家 Levent Alpöge 公布一份 PDF 文档，声称与 Claude 合作找到黎曼猜想的证明，并放出整套 Lean 形式化证明代码，分 14 个压缩文件供下载，若转为完整文档篇幅超 25 万页。他表示该方法还能解决广义黎曼猜想并有望延伸。证明尚未经独立验证。对读者：AI 辅助数学证明进入可形式化核验阶段，关注 Lean 生态与后续同行评审进展。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/11/511727.html" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="ainews-黎曼猜想被两次独立证明" tabindex="-1">AINews：黎曼猜想被两次独立证明 <a class="header-anchor" href="#ainews-黎曼猜想被两次独立证明" aria-label="Permalink to &quot;AINews：黎曼猜想被两次独立证明&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Latent Space</span><time datetime="2026-11-21">2026-11-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/637b117c49ed.png" alt="配图"></p><p>Latent Space 的 AI 新闻简报以「黎曼猜想被两次独立证明」为题，记录 11 月 20 日的这一进展，反映社区对 AI 参与数学发现的高度关注。对读者：可把该简报作为追踪事件时间线的入口，留意后续验证结论。</p><p class="news-entry-source"><a href="https://latent.space/p/ainews-riemann-hypothesis-proved-twice-independently/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="财报再亮眼也没用-黄仁勋想回去-英伟达董事会偏不让" tabindex="-1">财报再亮眼也没用：黄仁勋想回去，英伟达董事会偏不让 <a class="header-anchor" href="#财报再亮眼也没用-黄仁勋想回去-英伟达董事会偏不让" aria-label="Permalink to &quot;财报再亮眼也没用：黄仁勋想回去，英伟达董事会偏不让&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-21">2026-11-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/af7fa5f1be47.webp" alt="配图"></p><p>黄仁勋于 11 月 11 日辞去英伟达总裁、CEO 和董事会成员职务，CFO Colette Kress 暂代 CEO。首份「后黄时代」财报超预期，但董事会仍拒绝其回归，并开始物色正式接班人。对读者：英伟达短期产品规划已定，长期走向取决于下一任 CEO 的能力。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/3xzCDJBbDREm4EJFJWrH?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="林俊旸新公司估值升至-50-亿美元-丁磊谈短剧冲击游戏-华为星芒发布首款阔直板手机" tabindex="-1">林俊旸新公司估值升至 50 亿美元；丁磊谈短剧冲击游戏；华为星芒发布首款阔直板手机 <a class="header-anchor" href="#林俊旸新公司估值升至-50-亿美元-丁磊谈短剧冲击游戏-华为星芒发布首款阔直板手机" aria-label="Permalink to &quot;林俊旸新公司估值升至 50 亿美元；丁磊谈短剧冲击游戏；华为星芒发布首款阔直板手机&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">极客公园</span><time datetime="2026-11-21">2026-11-21</time></p><p>据彭博社报道，阿里前 AI 负责人林俊旸创办的语用科技完成新一轮数千万美元融资，估值达 50 亿美元，几个月内翻倍多，新投资方包括华业天成资本、鼎晖投资和吉利汽车。公司总部上海，致力于数字与物理世界的 AI 智能体。对读者：AI 智能体赛道估值升温，关注其首轮投资方红杉中国、腾讯等的后续动作。</p><p class="news-entry-source"><a href="http://www.geekpark.net/news/374299" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="anthropic-上市后能否坚持安全优先" tabindex="-1">Anthropic 上市后能否坚持安全优先？ <a class="header-anchor" href="#anthropic-上市后能否坚持安全优先" aria-label="Permalink to &quot;Anthropic 上市后能否坚持安全优先？&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-21">2026-11-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/cfca30b84454.jpg" alt="配图"></p><p>The Verge 播客讨论 Anthropic 于上周四在纳斯达克上市后的治理问题：公司已成为全球最有价值公司之一，真正的问题是它能否在成为对股东负责的上市公司后，继续在 AI 安全上投入。节目还对比了导致黄仁勋从英伟达辞职的治理结构并不适用于 Anthropic。对读者：关注 Anthropic 上市后的安全承诺与商业化节奏是否出现张力。</p><p class="news-entry-source"><a href="https://www.theverge.com/podcast/1038701/anthropic-ipo-ai-safety-openai-nvidia-structure" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="google-搜索首页改版-加入-ai-聊天历史-取消搜索按钮" tabindex="-1">Google 搜索首页改版：加入 AI 聊天历史，取消搜索按钮 <a class="header-anchor" href="#google-搜索首页改版-加入-ai-聊天历史-取消搜索按钮" aria-label="Permalink to &quot;Google 搜索首页改版：加入 AI 聊天历史，取消搜索按钮&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Ars Technica AI</span><time datetime="2026-11-21">2026-11-21</time></p><p>Google 搜索推出新版首页，让用户更容易在搜索页面直接访问 AI 工具，新增 AI 聊天历史入口，并移除了传统搜索按钮。这标志着搜索入口进一步向对话式 AI 倾斜。对读者：前端与产品团队可关注搜索交互范式变化对 SEO 与流量入口的影响。</p><p class="news-entry-source"><a href="https://arstechnica.com/ai/2026/11/googles-latest-search-page-redesign-drops-the-search-button-adds-ai-sidebar/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="chess-com-推经典游戏中心-涵盖麻将、数独等-10-款游戏" tabindex="-1">Chess.com 推经典游戏中心，涵盖麻将、数独等 10 款游戏 <a class="header-anchor" href="#chess-com-推经典游戏中心-涵盖麻将、数独等-10-款游戏" aria-label="Permalink to &quot;Chess.com 推经典游戏中心，涵盖麻将、数独等 10 款游戏&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-11-21">2026-11-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/4f74a621a315.jpg" alt="配图"></p><p>Chess.com 在推出无赌博扑克站 Gambit 后，再新增西洋双陆棋、跳棋、围棋、红心大战、麻将、将棋、数独、纸牌、象棋和类 Scrabble 的 word 共 10 款游戏，组成 Classic Games 平台，周六在 Web 及 iOS/Android 新应用上公测。对读者：垂直平台向多品类扩张是增长路径，可观察其社区运营与变现方式。</p><p class="news-entry-source"><a href="https://www.theverge.com/games/1038099/chess-classic-games-expansion-ai" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="openai-发布-gpt-live-1-1-语音智能体模型-闲置成本降至-0-02-美元-分钟" tabindex="-1">OpenAI 发布 GPT-Live-1.1 语音智能体模型，闲置成本降至 0.02 美元/分钟 <a class="header-anchor" href="#openai-发布-gpt-live-1-1-语音智能体模型-闲置成本降至-0-02-美元-分钟" aria-label="Permalink to &quot;OpenAI 发布 GPT-Live-1.1 语音智能体模型，闲置成本降至 0.02 美元/分钟&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-21">2026-11-21</time></p><p>OpenAI 在 API 中发布全双工语音模型 GPT-Live-1.1，改进多语言口音与转写能力，并新增待机模式：闲置 WebRTC 时间按每分钟 0.02 美元计费，此前为 0.05 美元。对读者：语音 Agent 的常驻成本明显下降，适合重新评估长连接语音产品的单位经济模型。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/21/openai-gpt-live-1-1-api-standby-mode/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="thinking-machines-发布-inkling-2-mini-26b-循环-moe-可在-32gb-mac-运行" tabindex="-1">Thinking Machines 发布 Inkling 2 Mini：26B 循环 MoE 可在 32GB Mac 运行 <a class="header-anchor" href="#thinking-machines-发布-inkling-2-mini-26b-循环-moe-可在-32gb-mac-运行" aria-label="Permalink to &quot;Thinking Machines 发布 Inkling 2 Mini：26B 循环 MoE 可在 32GB Mac 运行&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-21">2026-11-21</time></p><p>Thinking Machines 发布 Inkling 2 Mini，26.4B 参数循环 MoE Transformer，激活参数 3.4B，可在 32GB Mac 或单台 DGX Spark 上运行，SWE-bench Verified 得分 79.2%。对读者：端侧编码模型能力提升，本地开发与隐私敏感场景可优先评估该模型。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/21/thinking-machines-inkling-2-mini-looped-transformer/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="radixark-发布-daisyrose-27b-纯强化学习训练的-agent-编码模型" tabindex="-1">RadixArk 发布 DaisyRose-27B：纯强化学习训练的 Agent 编码模型 <a class="header-anchor" href="#radixark-发布-daisyrose-27b-纯强化学习训练的-agent-编码模型" aria-label="Permalink to &quot;RadixArk 发布 DaisyRose-27B：纯强化学习训练的 Agent 编码模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-21">2026-11-21</time></p><p>RadixArk 发布 DaisyRose-27B，基于 Qwen3.8-27B 仅用强化学习后训练，采用 Apache 2.0 协议，Terminal Bench 4.1 pass@1 从基线提升一倍多至 12.0，可在单 GPU 运行。对读者：开源 Agent 编码模型选择增多，可对比其与闭源模型在终端任务上的性价比。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/20/radixark-daisyrose-27b-agentic-model/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="baseten-发布-bison-1-与-groundhog-1-登顶决策模型指数" tabindex="-1">Baseten 发布 Bison-1 与 Groundhog-1，登顶决策模型指数 <a class="header-anchor" href="#baseten-发布-bison-1-与-groundhog-1-登顶决策模型指数" aria-label="Permalink to &quot;Baseten 发布 Bison-1 与 Groundhog-1，登顶决策模型指数&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-21">2026-11-21</time></p><p>Baseten 发布基于 Gemma 4 的开源权重决策模型 bison-1 与 groundhog-1，bison-1 在 AA Decision Index v2.1 上得分 76，两者均支持 128k 上下文和图像输入。对读者：决策类任务可关注开源权重模型的评测表现，评估替代闭源方案的可能。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/20/baseten-bison-1-groundhog-1-gemma-4-decision-models/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="deepseek-v1-作者创业项目曝光-开源本地-agent「linger」" tabindex="-1">DeepSeek V1 作者创业项目曝光：开源本地 Agent「Linger」 <a class="header-anchor" href="#deepseek-v1-作者创业项目曝光-开源本地-agent「linger」" aria-label="Permalink to &quot;DeepSeek V1 作者创业项目曝光：开源本地 Agent「Linger」&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-11-21">2026-11-21</time></p><p>前 DeepSeek V1 作者、DeepSeek-VL 项目负责人 Tony Zhang 公布创业项目 Linger，定位个人 Personal Agent，优先做电脑端，可操作用户已有网页、邮件和日历，支持人工接管与接入第三方模型，并专为本地 LLM 优化：12GB 显存 RTX 3060 可跑 125B 参数 Qwen3.8-Flash-Next，生成速度 45.5 tokens/秒。系统开源。对读者：本地优先的开源 Agent 值得跟进，关注其模型兼容性与权限设计。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/11/511570.html" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="entire-git-forge-面向编码智能体重构-git-协作方式" tabindex="-1">Entire Git Forge：面向编码智能体重构 Git 协作方式 <a class="header-anchor" href="#entire-git-forge-面向编码智能体重构-git-协作方式" aria-label="Permalink to &quot;Entire Git Forge：面向编码智能体重构 Git 协作方式&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-21">2026-11-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/472684b5cdf9.jpg" alt="配图"></p><p>Entire 是面向开发者与 AI 编码智能体协同的 Git 托管平台，认为传统 PR 流程无法适配智能体高速生成、评审和迭代代码的模式。其核心是 trails 轨迹机制，用置顶式评估分数驱动合并决策，取代线性时间线；平台基于全分布式架构，代码推送性能达 GitHub 的 89 倍。对读者：多智能体协作开发的基础设施正在重构，可关注 trails 模式对评审流程的启发。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/6swrOq5xUXwVqrREwJwc?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="aws-推出分布式-kv-缓存-agent-技能-自托管-llm-成本降-40" tabindex="-1">AWS 推出分布式 KV 缓存 Agent 技能，自托管 LLM 成本降 40% <a class="header-anchor" href="#aws-推出分布式-kv-缓存-agent-技能-自托管-llm-成本降-40" aria-label="Permalink to &quot;AWS 推出分布式 KV 缓存 Agent 技能，自托管 LLM 成本降 40%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-11-21">2026-11-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/fdcc39be3d94.png" alt="配图"></p><p>在 GPU 上自托管 LLM 意味着每轮都要重算相同上下文。结合 Amazon ElastiCache 的分布式 KV 缓存可将推理成本降低最多 40%、首 token 时间缩短最多 80%。AWS Agent Toolkit 中的该技能可评估并配置缓存。对读者：自托管推理团队可优先验证 KV 缓存对长对话场景的收益。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/cut-self-hosted-llm-cost-and-latency-with-the-distributed-kv-caching-agent-skill/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="aws-quick-更新-更强大的流程、新版-web-体验与多-agent-协作" tabindex="-1">AWS Quick 更新：更强大的流程、新版 Web 体验与多 Agent 协作 <a class="header-anchor" href="#aws-quick-更新-更强大的流程、新版-web-体验与多-agent-协作" aria-label="Permalink to &quot;AWS Quick 更新：更强大的流程、新版 Web 体验与多 Agent 协作&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">AWS Machine Learning</span><time datetime="2026-11-21">2026-11-21</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/ad63503b82ec.png" alt="配图"></p><p>AWS Quick 是面向工作的 AI 工作空间，本次更新支持在聊天中构建和运行业务流程、在新版 Web 应用中梳理日程、同时从多个 Agent 获取更完整答案，并接入 Meta ads、Amplitude 等新数据源。对读者：企业 Agent 平台正从单点问答走向流程编排，可评估多 Agent 协作的落地场景。</p><p class="news-entry-source"><a href="https://aws.amazon.com/blogs/machine-learning/new-in-aws-quick-more-capable-flows-an-updated-web-experience-and-agents-that-work-together/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="cloudflare-收购-astro-前端框架之战底层逻辑变了" tabindex="-1">Cloudflare 收购 Astro：前端框架之战底层逻辑变了 <a class="header-anchor" href="#cloudflare-收购-astro-前端框架之战底层逻辑变了" aria-label="Permalink to &quot;Cloudflare 收购 Astro：前端框架之战底层逻辑变了&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-11-21">2026-11-21</time></p><p>Cloudflare 官宣收购 Astro，文章认为这不是普通技术并购，而是用服务端优先的内容框架补齐边缘计算入口，与 Vercel+Next.js 争夺开发者生态。对读者：前端框架选型需关注托管平台与框架的绑定关系，评估迁移与锁定风险。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7710412551133790246" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="vite-曝-cvss-9-1-漏洞-npm-run-dev-host-有风险" tabindex="-1">Vite 曝 CVSS 9.1 漏洞：npm run dev --host 有风险 <a class="header-anchor" href="#vite-曝-cvss-9-1-漏洞-npm-run-dev-host-有风险" aria-label="Permalink to &quot;Vite 曝 CVSS 9.1 漏洞：npm run dev --host 有风险&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-11-21">2026-11-21</time></p><p>Vite 新披露 CVSS 9.1 漏洞：使用 --host 暴露的 dev server 会把 URL 参数拼进生成的模块代码，导致注入执行。作者在 7.3.7 复现，7.3.8 修复后失效。对读者：尽快升级 Vite 至 7.3.8 及以上，避免在不可信网络暴露 dev server。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7710210162956238874" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',9)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
